    private static void Tone(string file){const int n=22050;using var b=new BinaryWriter(File.Create(file));b.Write("RIFF"u8);b.Write(36+n*2);b.Write("WAVEfmt "u8);b.Write(16);b.Write((short)1);b.Write((short)1);b.Write(44100);b.Write(88200);b.Write((short)2);b.Write((short)16);b.Write("data"u8);b.Write(n*2);for(int i=0;i<n;i++)b.Write((short)(Math.Sin(i*Math.Tau*440/44100)*1700*Math.Min(1,(n-i)/1000.0)));}
