            var damage=doc.Weapon(weaponId)["parameters"]!["damage"]!.GetValue<int>();Change(()=>doc.Weapon(weaponId)["parameters"]!["damage"]=damage+1);Undo();Check(doc.Weapon(weaponId)["parameters"]!["damage"]!.GetValue<int>()==damage,"GUI undo");Redo();Check(doc.Weapon(weaponId)["parameters"]!["damage"]!.GetValue<int>()==damage+1,"GUI redo");
            Check(Save(),"native validation and atomic save");Check(!doc.Dirty&&File.Exists(gp+".bak"),"backup and clean");Check(File.ReadAllText(Path.Combine(root,"assets.sha256")).Contains(Document.Hash(doc.EffectsPath)+"  weapon_effects.json"),"effect integrity entry");var old=File.ReadAllText(gp);Change(()=>doc.Weapon(weaponId)["parameters"]!["magazine"]=1001);Check(!Save(),"native reject illegal magazine");Check(File.ReadAllText(gp)==old,"invalid save leaves file intact");Undo();
