                Change(()=>{var a=EnsureLayers();a.Clear();a.Add(new JsonObject{["texture"]=0x668997,["count"]=8,["radius"]=250,["lifetimeMs"]=500,["speed"]=1500,["spread"]=1.0,["rotationRandom"]=3.0,["color"]=new JsonArray(.65,.025,.02,1),["atlas"]=new JsonObject{["columns"]=4,["rows"]=4,["frames"]=16,["fps"]=32}});EnsureEvent("lights","shot")["enabled"]=false;});Check(Save(),"original blood effect saved");preview.TimeMs=130;timeline.Value=130;originalPreview=true;
            }
