            }
            var beforeIcon=WeaponIcons.Override(doc.Weapon(weaponId));ImportIconFile(iconSource);var customIcon=WeaponIcons.Override(doc.Weapon(weaponId));Check(customIcon is not null&&customIcon.StartsWith("weapon_editor_assets/icons/",StringComparison.Ordinal),"icon imported into data relative JSON path");Check(iconPreview.Image is not null,"icon alpha preview loaded");Undo();Check(WeaponIcons.Override(doc.Weapon(weaponId))==beforeIcon,"icon undo");Redo();Check(WeaponIcons.Override(doc.Weapon(weaponId))==customIcon,"icon redo");Check(Save(),"native accepts icon JSON");Check(Document.Open(gp).Weapon(weaponId)["visual"]?["iconPath"]?.GetValue<string>()==customIcon,"saved icon path reopens");
            string fullIcon=Paths.Resolve(root,customIcon!);var accepted=File.ReadAllText(gp);File.Move(fullIcon,fullIcon+".held");Check(!Save(),"missing icon refuses save");Check(File.ReadAllText(gp)==accepted,"missing icon retains accepted settings");File.Move(fullIcon+".held",fullIcon);Check(Save(),"restored icon saves");Check(File.ReadAllText(Path.Combine(root,"assets.sha256")).Contains(Document.Hash(fullIcon)+"  "+customIcon),"icon integrity hash updated");
            tab.SelectedTab=tab.TabPages.Cast<TabPage>().Single(t=>t.Text=="アイコン");await Task.Delay(80);Refresh();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new(0,0,Width,Height));bitmap.Save(Path.Combine(output,"04-weapon-icon.png"));}
            timeline.Value=0;Play();await Task.Delay(140);Check(playing&&preview.TimeMs>0,"playback clock");Stop();Check(!playing,"stop playback");audio.Play(Paths.Resolve(root,soundPath),.3);await Task.Delay(100);audio.Stop();checks++;
            File.WriteAllText(Path.Combine(output,"gui-results.json"),JsonSerializer.Serialize(new{passed=true,checks,app=typeof(Native).Assembly.Location,sharedDllSha256=Document.Hash(Path.Combine(AppContext.BaseDirectory,"MGO2MTWpnEffects.dll")),originalPreview,originalAssetsBundled=false},Document.JsonOptions));Environment.ExitCode=0;
